import re
import pandas as pd
from datetime import datetime

_NUM_RE = re.compile(r'^[+-]?\d+(\.\d{1,2})?$')
_DATE_RE = re.compile(r'^\d{4}-\d{2}-\d{2}$')
_VALID_CUR = {'USD', 'EUR', 'GBP'}


def _is_null(v):
    if v is None:
        return True
    try:
        if isinstance(v, float) and pd.isna(v):
            return True
    except Exception:
        pass
    if pd.isna(v) if not isinstance(v, (list, dict)) else False:
        return True
    return False


def _trim(s):
    return s.strip()


def run(inputs: dict) -> dict:
    raw = inputs["raw_payments"]

    valid_rows = []
    reject_rows = []

    # First pass: apply R1-R5 in order, collect passing rows with parsed values
    passed = []  # list of dicts with row_num, payment_id_trimmed, account_id, amount, currency, pay_date

    for _, row in raw.iterrows():
        row_num = row['row_num']
        payment_id = row['payment_id']
        account_id = row['account_id']
        amount_txt = row['amount_txt']
        currency = row['currency']
        pay_date_txt = row['pay_date_txt']

        # R1 MISSING_ID
        if _is_null(payment_id):
            reject_rows.append((row_num, 'MISSING_ID'))
            continue
        pid_trimmed = _trim(str(payment_id))
        if pid_trimmed == '':
            reject_rows.append((row_num, 'MISSING_ID'))
            continue

        # R2 BAD_AMOUNT
        if _is_null(amount_txt):
            reject_rows.append((row_num, 'BAD_AMOUNT'))
            continue
        amt_trimmed = _trim(str(amount_txt))
        if not _NUM_RE.match(amt_trimmed):
            reject_rows.append((row_num, 'BAD_AMOUNT'))
            continue
        try:
            amount_val = float(amt_trimmed)
        except Exception:
            reject_rows.append((row_num, 'BAD_AMOUNT'))
            continue

        # R3 NON_POSITIVE
        if amount_val <= 0:
            reject_rows.append((row_num, 'NON_POSITIVE'))
            continue

        # R4 BAD_CURRENCY
        if _is_null(currency):
            reject_rows.append((row_num, 'BAD_CURRENCY'))
            continue
        cur_trimmed = _trim(str(currency)).upper()
        if cur_trimmed not in _VALID_CUR:
            reject_rows.append((row_num, 'BAD_CURRENCY'))
            continue

        # R5 BAD_DATE
        if _is_null(pay_date_txt):
            reject_rows.append((row_num, 'BAD_DATE'))
            continue
        date_trimmed = _trim(str(pay_date_txt))
        if not _DATE_RE.match(date_trimmed):
            reject_rows.append((row_num, 'BAD_DATE'))
            continue
        try:
            parsed_date = datetime.strptime(date_trimmed, '%Y-%m-%d').date()
        except ValueError:
            reject_rows.append((row_num, 'BAD_DATE'))
            continue

        passed.append({
            'row_num': row_num,
            'payment_id': pid_trimmed,
            'account_id': account_id,
            'amount': amount_val,
            'currency': cur_trimmed,
            'pay_date': parsed_date,
        })

    # R6 DUPLICATE: group by trimmed payment_id, keep lowest row_num per group
    if passed:
        passed_df = pd.DataFrame(passed)
        min_row_per_group = passed_df.groupby('payment_id')['row_num'].transform('min')
        is_valid_mask = passed_df['row_num'] == min_row_per_group

        valid_df_rows = passed_df[is_valid_mask]
        dup_df_rows = passed_df[~is_valid_mask]

        for _, r in valid_df_rows.iterrows():
            valid_rows.append((r['payment_id'], r['account_id'], r['amount'], r['currency'], r['pay_date']))

        for _, r in dup_df_rows.iterrows():
            reject_rows.append((r['row_num'], 'DUPLICATE'))

    valid_payments = pd.DataFrame(
        valid_rows,
        columns=['payment_id', 'account_id', 'amount', 'currency', 'pay_date']
    )

    payment_rejects = pd.DataFrame(
        reject_rows,
        columns=['row_num', 'reject_reason']
    )

    return {
        'valid_payments': valid_payments,
        'payment_rejects': payment_rejects,
    }
